import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.load(sys.stdin)
# Compare
def pkg_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages', []):
                m[(name, pkg['id'])] = pkg['resolvedVersion']
    return m
b = pkg_map(baseline)
a = pkg_map(after)
if b == a:
    print('All packages match baseline - no version changes.')
else:
    for k in sorted(set(list(b.keys()) + list(a.keys()))):
        bv = b.get(k, 'MISSING')
        av = a.get(k, 'MISSING')
        if bv != av:
            print(f'CHANGED: {k[0]} {k[1]}: {bv} -> {av}')
"

